      "must_do_id": null
    },
    {
      "poi_id": "p20",
      "kind": "activity",
      "must_do_id": null,
      "note": "Điều bất ngờ cho tối nay: chợ đêm ồn ào, thơm mùi bắp nướng, nhìn đời Đà Lạt thức dậy sau hoàng hôn.",
      "must_do_id": null
    },
    {
      "poi_id": "p157",
      "kind": "meal",
      "must_do_id": null,
      "note": "Bữa tối ngồi xuống đàng hoàng, nem nướng cuốn rau tươi, ngon quá, ăn chậm cho ấm bụng.",
      "must_do_id": null
    },
    {
      "poi_id": "p218",
      "kind": "activity",
      "must_do_id": null,
      "note": "Kết đêm bằng một quầy bar nhỏ, thứ người ta ít ngờ giữa phố núi, nhạc nhẹ và ánh đèn vàng.",
      "must_do_id": null
    }
  ]
}
